{
  "headline": "Prioritize indoor air quality and strategic outdoor timing",
  "summary": "Today's air quality is {{level.name}} with a US AQI of {{aqi.now}}. Running air purifiers indoors can reduce your exposure by {{impact.run_purifier_through_night.pct}}, and the best time for outdoor activities is between {{best.start}} and {{best.end}}.",
  "cards": [
    {
      "actionId": "run_purifier_through_night",
      "title": "Run air purifiers continuously",
      "why": "Continuous mechanical filtration provides the most significant reduction in indoor PM2.5 exposure, lowering it by {{impact.run_purifier_through_night.pct}}.",
      "when": "Run throughout the night and during all home hours.",
      "steps": [
        "Close bedroom doors to concentrate filtration in occupied spaces.",
        "Ensure air purifiers are set to their highest effective setting."
      ]
    },
    {
      "actionId": "shift_exercise_to_best_window",
      "title": "Schedule outdoor exercise during cleaner periods",
      "why": "Exercising outdoors during the best air quality window can reduce exposure by {{impact.shift_exercise_to_best_window.pct}}.",
      "when": "Plan outdoor exercise between {{best.start}} and {{best.end}}.",
      "steps": [
        "Check the air quality forecast before planning outdoor activities.",
        "Consider shorter, less intense outdoor sessions if the window is narrow."
      ]
    },
    {
      "actionId": "avoid_indoor_smoke_sources",
      "title": "Minimize indoor smoke and pollutant sources",
      "why": "Avoiding indoor smoke sources can reduce exposure by {{impact.avoid_indoor_smoke_sources.pct}}.",
      "when": "Implement these practices consistently.",
      "steps": [
        "Avoid burning incense or candles indoors.",
        "Ensure proper ventilation when cooking, especially with gas stoves."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for a community-wide \"no burning\" policy",
      "why": "Community-wide efforts can significantly improve local air quality, potentially reducing exposure by {{impact.community_no_burning.pct}}.",
      "when": "Discuss with neighbors and local authorities regularly.",
      "steps": [
        "Raise awareness about the impact of open burning.",
        "Support initiatives for cleaner waste management."
      ]
    },
    {
      "actionId": "damp_mop_dont_sweep",
      "title": "Use damp mopping instead of dry sweeping",
      "why": "Damp mopping effectively captures dust and particles, reducing airborne levels by {{impact.damp_mop_dont_sweep.pct}}, unlike dry sweeping which can re-suspend them.",
      "when": "Perform regular floor cleaning.",
      "steps": [
        "Use a damp cloth or mop for cleaning surfaces.",
        "Avoid using brooms for dry sweeping whenever possible."
      ]
    },
    {
      "actionId": "errands_in_best_window",
      "title": "Plan errands during the best air quality window",
      "why": "Conducting errands during optimal air quality times can reduce overall exposure.",
      "when": "Schedule outdoor errands between {{best.start}} and {{best.end}}.",
      "steps": [
        "Group errands together to minimize travel time outdoors.",
        "Check air quality before leaving home."
      ]
    },
    {
      "actionId": "share_community_brief",
      "title": "Share the Community Air Quality Brief",
      "why": "Informing your community can lead to collective action and improved air quality, potentially reducing exposure by {{impact.share_community_brief.pct}}.",
      "when": "Share with your Resident Welfare Association (RWA) or community leaders.",
      "steps": [
        "Distribute the brief through community channels.",
        "Encourage discussion on local air pollution sources."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "adult",
      "note": "Consider reducing strenuous outdoor activities when air quality is {{level.name}}."
    },
    {
      "group": "child",
      "note": "Limit children's time spent outdoors while the air quality remains {{level.name}}."
    }
  ],
  "tradeoffs": []
}
